<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { resourceApi, resourceFolderApi, genTypeApi } from '@/api/modules'
import GlassCard from '@/v2/components/GlassCard.vue'
import GlassDrawer from '@/v2/components/GlassDrawer.vue'
import StatusBadge from '@/v2/components/StatusBadge.vue'
import V2Button from '@/v2/components/V2Button.vue'
import V2Field from '@/v2/components/V2Field.vue'
import FolderTree from './FolderTree.vue'
import ResourceCard from './ResourceCard.vue'
import ResourceDetailDrawer from './ResourceDetailDrawer.vue'
import BatchSingleImageTaskModal from './BatchSingleImageTaskModal.vue'
import ImageGalleryViewer from './ImageGalleryViewer.vue'
import { flattenGenerationMenu, type GenerationTypeItem } from '@/v2/features/tasks/model'
import { flattenFolders, localDateKey, type FolderNode, type ResourceItem } from './model'
import { useResourceThumbs } from './useResourceThumbs'
const PAGE=30;const MAX_UPLOAD_SIZE=2*1024*1024*1024;const tree=ref<FolderNode[]>([]);const currentId=ref<number|null>(null);const expanded=ref(new Set<number>());const items=ref<ResourceItem[]>([]);const selected=ref(new Set<number>());const media=ref('');const direction=ref('');const keyword=ref('');const loading=ref(false);const loadingMore=ref(false);const hasMore=ref(true);const detail=ref<ResourceItem|null>(null);const folderDialog=ref(false);const folderName=ref('');const editing=ref(false);const moveDialog=ref(false);const moveTarget=ref<number|null>(null);const deleting=ref(false);const folderPanelOpen=ref(false);const uploadInput=ref<HTMLInputElement|null>(null);const loadVersion={n:0};const {thumbs,load:loadThumbs,clear}=useResourceThumbs()
const uploading=ref(false);const uploadNotice=ref('');const uploadError=ref('')
const storageSummary=ref<{total_bytes:number;active_bytes:number;recycle_bin_bytes:number;total_count:number;active_count:number;recycle_bin_count:number}|null>(null)
const router=useRouter()
const galleryOpen=ref(false);const galleryLoading=ref(false);const galleryImages=ref<ResourceItem[]>([]);const galleryStartId=ref<number|null>(null);const galleryFolderId=ref<number|null>(null);let galleryRequest=0
const actionMenuOpen=ref(false);const actionType=ref<'image_ops'|'gen_video'|'single_image_task'|'single_image_video_task'>('image_ops');const genMenu=ref<GenerationTypeItem[]>([]);const batchSingleTaskOpen=ref(false);const batchSingleTaskType=ref<GenerationTypeItem|null>(null);const actionNotice=ref('')
const cropDialog=ref(false);const cropRatio=ref('1:1');const cropping=ref(false);const cropRatios=[{value:'1:1',label:'方形'},{value:'4:3',label:'横向标准'},{value:'3:4',label:'竖向标准'},{value:'3:2',label:'横向照片'},{value:'2:3',label:'竖向照片'},{value:'16:9',label:'横屏'},{value:'9:16',label:'竖屏'},{value:'21:9',label:'超宽屏'}]
const selectedImageIds=computed(()=>[...selected.value].filter(id=>{const item=items.value.find(i=>i.id===id);return item?.media_type==='image'}))
const selectedVideoIds=computed(()=>[...selected.value].filter(id=>{const item=items.value.find(i=>i.id===id);return item?.media_type==='video'}))
const allLoadedSelected=computed(()=>items.value.length>0&&items.value.every(item=>selected.value.has(item.id)))
function hasSingleImageInput(item:GenerationTypeItem){const schema=item.param_schema||[];return !schema.length||schema.some(parameter=>parameter.type==='image'&&!parameter.multiple)}
const filteredGenMenu=computed(()=>{if(!genMenu.value.length)return[];if(actionType.value==='image_ops')return genMenu.value.filter(t=>t.media_type==='image'&&t.code!=='t2i');if(actionType.value==='gen_video')return genMenu.value.filter(t=>t.media_type==='video'&&t.code!=='t2v');if(actionType.value==='single_image_video_task')return genMenu.value.filter(t=>t.media_type==='video'&&t.code!=='t2v'&&hasSingleImageInput(t));return genMenu.value.filter(t=>['image','video'].includes(t.media_type)&&!['t2i','t2v'].includes(t.code)&&hasSingleImageInput(t))})
async function loadGenMenu(){if(genMenu.value.length)return;try{const menu=await genTypeApi.menu();genMenu.value=flattenGenerationMenu(menu)}catch{}}
function openActionMenu(type:'image_ops'|'gen_video'|'single_image_task'|'single_image_video_task'){actionType.value=type;actionMenuOpen.value=true;void loadGenMenu()}
function pickGenType(item:GenerationTypeItem){if(!selectedImageIds.value.length)return;actionMenuOpen.value=false;if(actionType.value==='single_image_task'||actionType.value==='single_image_video_task'){batchSingleTaskType.value=item;batchSingleTaskOpen.value=true;return}const ids=selectedImageIds.value.join(',');selected.value=new Set();router.push({path:`/v2/generate/${item.code}`,query:{resource_ids:ids}})}
function batchSingleTaskCreated(result:{batchId:number;enqueued:number;invalid:number}){batchSingleTaskOpen.value=false;batchSingleTaskType.value=null;selected.value=new Set();actionNotice.value=`批次 #${result.batchId} 已创建：${result.enqueued} 个任务已入队${result.invalid?`，${result.invalid} 个任务参数无效`:''}`}
function openCrop(){if(!selectedImageIds.value.length)return;cropRatio.value='1:1';cropDialog.value=true}
async function batchCrop(){if(!selectedImageIds.value.length||cropping.value)return;cropping.value=true;actionNotice.value='';try{const result=await resourceApi.batchCrop(selectedImageIds.value,cropRatio.value);cropDialog.value=false;direction.value='';media.value='image';await Promise.all([loadTree(),load(),loadStorageSummary()]);selected.value=new Set(result.created.map(item=>item.id));actionNotice.value=`已按 ${cropRatio.value} 裁剪生成 ${result.created.length} 张图片${result.failed.length?`，${result.failed.length} 张失败`:''}`;if(!result.created.length&&result.failed.length)alert(result.failed.map(item=>`#${item.resource_id}：${item.reason}`).join('\n'))}catch(e:any){alert(e?.response?.data?.detail||e?.message||'批量裁剪失败')}finally{cropping.value=false}}
async function mergeVideos(){if(selectedVideoIds.value.length<2)return;if(!confirm(`确认合并选中的 ${selectedVideoIds.value.length} 个视频？\n按选中顺序拼接，保存为新视频。`))return;try{const result=await resourceApi.mergeVideos(selectedVideoIds.value);alert(`合并完成：${result.filename}`);selected.value=new Set();await Promise.all([load(),loadTree(),loadStorageSummary()])}catch(e:any){alert(e?.response?.data?.detail||e?.message||'合并失败')}}
const flat=computed(()=>flattenFolders(tree.value));const current=computed(()=>flat.value.find(v=>v.id===currentId.value));const normalFolder=computed(()=>current.value?.folder_type==='normal')
/** 可作为移动目标的目录（排除当前目录及其所有后代，仅 normal 类型） */
const movableFolderTargets = computed(() => {
  if (!current.value) return []
  const currentId = current.value.id
  const collectDescendants = (id: number): Set<number> => {
    const result = new Set<number>()
    const stack = [id]
    while (stack.length) {
      const fid = stack.pop()!
      for (const f of flat.value) {
        if (f.parent_id === fid && !result.has(f.id)) { result.add(f.id); stack.push(f.id) }
      }
    }
    return result
  }
  const exclude = new Set<number>([currentId, ...collectDescendants(currentId)])
  return flat.value.filter(f => !exclude.has(f.id) && f.folder_type === 'normal')
})
function expandAncestors(id:number|null){const next=new Set(expanded.value);let node=flat.value.find(v=>v.id===id);while(node?.parent_id){next.add(node.parent_id);node=flat.value.find(v=>v.id===node?.parent_id)}expanded.value=next}
async function loadTree(defaultToday=false){tree.value=await resourceFolderApi.tree();if(defaultToday||!flat.value.some(v=>v.id===currentId.value)){const key=`task_results:${localDateKey()}`;currentId.value=flat.value.find(v=>v.system_key===key)?.id??flat.value.find(v=>v.system_key==='task_results')?.id??flat.value[0]?.id??null;expandAncestors(currentId.value)}}
async function load(reset=true){const myRequest=loadVersion.n+1;loadVersion.n=myRequest;reset?loading.value=true:loadingMore.value=true;try{if(reset){items.value=[];clear()}const page=await resourceApi.list({folder_id:currentId.value||undefined,media_type:media.value||undefined,direction:direction.value||undefined,keyword:keyword.value||undefined,limit:PAGE,offset:reset?0:items.value.length});if(myRequest!==loadVersion.n)return;const unique=new Map<number,ResourceItem>();for(const item of items.value)unique.set(item.id,item);for(const item of page as ResourceItem[])unique.set(item.id,item);items.value=Array.from(unique.values());hasMore.value=page.length===PAGE;void loadThumbs(page)}finally{if(myRequest===loadVersion.n){loading.value=false;loadingMore.value=false}}}
function formatBytes(value:number){if(value<=0)return'0 B';const units=['B','KB','MB','GB','TB'];const index=Math.min(Math.floor(Math.log(value)/Math.log(1024)),units.length-1);const amount=value/1024**index;return`${amount.toFixed(index===0?0:amount>=100?0:amount>=10?1:2)} ${units[index]}`}
async function loadStorageSummary(){try{storageSummary.value=await resourceApi.storageSummary()}catch{storageSummary.value=null}}
async function refreshLibrary(){if(loading.value||loadingMore.value)return;await Promise.all([loadTree(),load(),loadStorageSummary()])}
async function loadGalleryFolder(folderId:number|null,startId?:number){
  const request=++galleryRequest
  galleryFolderId.value=folderId;galleryOpen.value=true;galleryLoading.value=true;galleryImages.value=[];galleryStartId.value=null;actionNotice.value='';uploadError.value=''
  try{
    const images:ResourceItem[]=[];const seen=new Set<number>();const limit=200
    for(let offset=0;;offset+=limit){
      const page=await resourceApi.list({folder_id:folderId||undefined,media_type:'image',direction:direction.value||undefined,keyword:keyword.value||undefined,limit,offset}) as ResourceItem[]
      if(request!==galleryRequest)return
      for(const item of page)if(!seen.has(item.id)){seen.add(item.id);images.push(item)}
      if(page.length<limit)break
    }
    if(request!==galleryRequest)return
    galleryImages.value=images
    galleryStartId.value=startId??selectedImageIds.value.find(id=>seen.has(id))??images[0]?.id??null
  }catch(e:any){uploadError.value=e?.response?.data?.detail||e?.message||'读取图片失败'}
  finally{if(request===galleryRequest)galleryLoading.value=false}
}
function openGallery(startId?:number){void loadGalleryFolder(currentId.value,startId)}
function changeGalleryFolder(folderId:number|null){void loadGalleryFolder(folderId)}
function toggle(id:number){const next=new Set(expanded.value);next.has(id)?next.delete(id):next.add(id);expanded.value=next}function choose(id:number){currentId.value=id;selected.value=new Set();folderPanelOpen.value=false}function select(id:number){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next}
function toggleSelectAll(){selected.value=allLoadedSelected.value?new Set():new Set(items.value.map(item=>item.id))}
function openCreate(){editing.value=false;folderName.value='';folderDialog.value=true}function openRename(){if(!normalFolder.value)return;editing.value=true;folderName.value=current.value?.name||'';folderDialog.value=true}
const moveFolderDialog=ref(false)
const moveFolderTargetStr=ref('')
const movingFolder=ref(false)
function openMoveFolder(){if(!normalFolder.value||!currentId.value)return;moveFolderTargetStr.value='';moveFolderDialog.value=true}
async function moveFolderConfirm(){
  if(!currentId.value||movingFolder.value)return
  const movingFolderId=currentId.value
  const parentId=moveFolderTargetStr.value===''?null:Number(moveFolderTargetStr.value)
  movingFolder.value=true
  actionNotice.value=''
  try{
    await resourceFolderApi.patch(movingFolderId,{parent_id:parentId,move:true})
    moveFolderDialog.value=false
    await loadTree()
    if(parentId){currentId.value=parentId;expandAncestors(parentId)}
    await load()
    actionNotice.value=`目录“${flat.value.find(folder=>folder.id===movingFolderId)?.name||'所选目录'}”已移动`
  }catch(e:any){alert(e?.response?.data?.detail||e?.message||'移动失败')}
  finally{movingFolder.value=false}
}
async function saveFolder(){if(!folderName.value.trim())return;if(editing.value&&currentId.value)await resourceFolderApi.patch(currentId.value,{name:folderName.value});else await resourceFolderApi.create({name:folderName.value,parent_id:normalFolder.value?currentId.value:null});folderDialog.value=false;await loadTree()}
async function deleteFolder(){if(!normalFolder.value||!currentId.value||!confirm(`删除空目录“${current.value?.name}”？\n目录中存在素材或子目录时不能删除。`))return;try{await resourceFolderApi.delete(currentId.value);await loadTree(true);await load()}catch(e:any){alert(e?.response?.data?.detail||e?.message||'删除目录失败')}}
function openMove(id?:number){if(id)selected.value=new Set([id]);if(!selected.value.size)return;moveTarget.value=currentId.value;moveDialog.value=true}async function move(){await resourceApi.batchMove([...selected.value],moveTarget.value);moveDialog.value=false;selected.value=new Set();await loadTree();await load()}
function openUploadPicker(){uploadError.value='';uploadNotice.value='';uploadInput.value?.click()}
async function uploadFiles(files:FileList|null){
  if(!files?.length)return
  const oversized=[...files].find(file=>file.size>MAX_UPLOAD_SIZE)
  if(oversized){uploadNotice.value='';uploadError.value=`文件“${oversized.name}”超过 2GB 上限`;if(uploadInput.value)uploadInput.value.value='';return}
  uploading.value=true;uploadError.value='';uploadNotice.value=''
  const uploaded:number[]=[]
  try{
    for(const file of [...files]){
      const type=file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'image'
      const saved=await resourceApi.upload(file,type,'input') as ResourceItem
      if(currentId.value&&saved.folder_id!==currentId.value)await resourceApi.move(saved.id,currentId.value)
      uploaded.push(saved.id)
    }
    direction.value='';keyword.value=''
    await Promise.all([loadTree(),load(),loadStorageSummary()])
    selected.value=new Set(uploaded)
    uploadNotice.value=`已上传 ${uploaded.length} 个素材`
  }catch(e:any){uploadError.value=e?.response?.data?.detail||e?.message||'上传失败，请重试'}
  finally{uploading.value=false;if(uploadInput.value)uploadInput.value.value=''}
}
async function batchDelete(){if(!selected.value.size)return;deleting.value=true;try{const result=await resourceApi.batchDelete([...selected.value]);const msg=`已移入回收站 ${result.deleted} 项${result.failed?.length?`，${result.failed.length} 项失败`:''}`;alert(msg);selected.value=new Set();await Promise.all([loadTree(),load(),loadStorageSummary()])}catch(e:any){alert(e?.response?.data?.detail||e?.message||'删除失败')}finally{deleting.value=false}}
onMounted(async()=>{await loadTree(true);await Promise.all([load(),loadStorageSummary()])});watch(currentId,()=>void load());let searchTimer:ReturnType<typeof setTimeout>|null=null;watch(keyword,()=>{if(searchTimer)clearTimeout(searchTimer);searchTimer=setTimeout(()=>void load(),350)})
</script>
<template><div class="v2-page"><div class="v2-page-heading heading"><div><StatusBadge tone="success">素材中心</StatusBadge><h1>素材库</h1><p>{{ current?.name||'目录' }} · 已加载 {{ items.length }} 项 · 单个文件最大 2GB</p><p v-if="storageSummary" class="storage-summary" title="包含素材库和回收站中的素材文件，不重复计算相同存储文件"><b>总占用 {{ formatBytes(storageSummary.total_bytes) }}</b><span>在库 {{ formatBytes(storageSummary.active_bytes) }} · 回收站 {{ formatBytes(storageSummary.recycle_bin_bytes) }} · 共 {{ storageSummary.total_count }} 项</span></p><p v-if="uploadNotice" class="upload-notice" role="status">{{ uploadNotice }}</p><p v-if="actionNotice" class="upload-notice" role="status">{{ actionNotice }}</p><p v-if="uploadError" class="upload-error" role="alert">{{ uploadError }}</p></div><div class="head-actions"><input ref="uploadInput" type="file" multiple accept="image/*,video/*,audio/*" hidden @change="uploadFiles(($event.target as HTMLInputElement).files)"/><V2Button variant="ghost" :disabled="loading||loadingMore" @click="refreshLibrary">{{ loading?'刷新中…':'刷新' }}</V2Button><V2Button variant="ghost" :disabled="galleryLoading" @click="openGallery()">{{ galleryLoading?'读取图片…':'图片浏览' }}</V2Button><V2Button :disabled="uploading" @click="openUploadPicker">{{ uploading?'上传中…':'上传素材' }}</V2Button><V2Button variant="primary" @click="openCreate">新建目录</V2Button></div></div><div class="library"><GlassCard padding="sm" class="folder-panel" :class="{open:folderPanelOpen}"><div class="folder-tools"><b>目录</b><button @click="expanded=new Set(flat.map(v=>v.id))">展开</button><button @click="expanded=new Set()">折叠</button></div><FolderTree :tree="tree" :current-id="currentId" :expanded="expanded" @select="choose" @toggle="toggle"/><div v-if="normalFolder" class="folder-actions"><V2Button variant="ghost" @click="openRename">重命名</V2Button><V2Button variant="ghost" @click="openMoveFolder">移动</V2Button><V2Button variant="danger" @click="deleteFolder">删除</V2Button></div></GlassCard><main><div class="mobile-folder-bar" @click="folderPanelOpen=!folderPanelOpen"><b>{{ current?.name||'选择目录' }}</b><span>{{ folderPanelOpen?'▲':'▼' }}</span></div><GlassCard padding="sm"><div class="filters"><V2Field label="搜索"><input v-model="keyword" placeholder="文件名称"/></V2Field><V2Field label="媒体类型"><select v-model="media" @change="load()"><option value="">全部</option><option value="image">图片</option><option value="video">视频</option><option value="audio">音频</option></select></V2Field><V2Field label="素材来源"><select v-model="direction" @change="load()"><option value="">全部</option><option value="input">上传素材</option><option value="output">任务结果</option></select></V2Field><V2Button variant="ghost" :disabled="loading||!items.length" @click="toggleSelectAll">{{ allLoadedSelected?'取消全选':'全选' }}</V2Button></div></GlassCard><div class="resource-grid"><ResourceCard v-for="item in items" :key="item.id" :item="item" :thumb="thumbs[item.id]" :selected="selected.has(item.id)" @open="detail=item" @select="select(item.id)"/><p v-if="!items.length&&!loading" class="empty">当前目录没有素材</p></div><div class="load-more"><V2Button v-if="hasMore" :disabled="loadingMore" @click="load(false)">{{ loadingMore?'加载中…':'加载更多' }}</V2Button></div></main></div>
<div v-if="selected.size" class="floating-bar"><span class="fb-count">已选 {{ selected.size }} 项</span><div class="fb-actions"><button @click="openMove()">移动</button><button v-if="selectedImageIds.length" @click="openCrop">批量裁剪</button><button v-if="selectedImageIds.length" @click="openActionMenu('single_image_video_task')">批量图生视频任务</button><button v-if="selectedImageIds.length" @click="openActionMenu('single_image_task')">批量单图任务</button><button v-if="selectedImageIds.length" @click="openActionMenu('image_ops')">图片操作</button><button v-if="selectedImageIds.length" @click="openActionMenu('gen_video')">生成视频</button><button v-if="selectedVideoIds.length>=2" @click="mergeVideos">合并视频</button><button class="fb-danger" :disabled="deleting" @click="batchDelete">{{ deleting?'删除中…':'移入回收站' }}</button><button class="fb-clear" @click="selected=new Set()" aria-label="关闭"><StudioIcon name="close"/></button></div></div>
<ResourceDetailDrawer :open="!!detail" :resource="detail" @close="detail=null" @deleted="load();loadTree();loadStorageSummary()"/><GlassDrawer :open="folderDialog" :title="editing?'重命名目录':'新建目录'" @close="folderDialog=false"><V2Field label="目录名称" required><input v-model="folderName" @keyup.enter="saveFolder"/></V2Field><div class="drawer-actions"><V2Button variant="primary" @click="saveFolder">保存</V2Button></div></GlassDrawer><GlassDrawer :open="moveDialog" title="移动素材" @close="moveDialog=false"><V2Field label="目标目录"><select v-model="moveTarget"><option v-for="folder in flat" :key="folder.id" :value="folder.id">{{ '　'.repeat(folder.depth) }}{{ folder.name }}</option></select></V2Field><div class="drawer-actions"><V2Button variant="primary" @click="move">确认移动</V2Button></div></GlassDrawer><GlassDrawer :open="cropDialog" title="批量裁剪图片" @close="cropDialog=false"><p class="crop-hint">将 {{ selectedImageIds.length }} 张图片按相同比例居中裁剪。原图会保留，裁剪结果保存到原目录。</p><div class="crop-ratios"><button v-for="ratio in cropRatios" :key="ratio.value" type="button" :class="{active:cropRatio===ratio.value}" :disabled="cropping" @click="cropRatio=ratio.value"><b>{{ ratio.value }}</b><span>{{ ratio.label }}</span></button></div><div class="drawer-actions"><V2Button variant="ghost" :disabled="cropping" @click="cropDialog=false">取消</V2Button><V2Button variant="primary" :disabled="cropping" @click="batchCrop">{{ cropping?'裁剪中…':`裁剪 ${selectedImageIds.length} 张图片` }}</V2Button></div></GlassDrawer><GlassDrawer :open="moveFolderDialog" :title="`移动目录：${current?.name||''}`" @close="moveFolderDialog=false"><p class="move-folder-hint">选择新的父目录（不能选自身或子目录）：</p><select v-model="moveFolderTargetStr" class="folder-select" :disabled="movingFolder"><option value="">— 顶层（无父目录） —</option><option v-for="folder in movableFolderTargets" :key="folder.id" :value="String(folder.id)">{{ '　'.repeat(folder.depth) }}{{ folder.name }}</option></select><div class="drawer-actions"><V2Button variant="ghost" :disabled="movingFolder" @click="moveFolderDialog=false">取消</V2Button><V2Button variant="primary" :disabled="movingFolder" @click="moveFolderConfirm">{{ movingFolder?'移动中…':'确认移动' }}</V2Button></div></GlassDrawer>
<div v-if="actionMenuOpen" class="action-menu-overlay" @click.self="actionMenuOpen=false"><div class="action-menu"><header><h3>{{ actionType==='image_ops'?'批量图片操作':actionType==='gen_video'?'批量生成视频':actionType==='single_image_video_task'?'选择图生视频任务':'选择单图任务' }} · {{ selectedImageIds.length }} 张</h3><button @click="actionMenuOpen=false" aria-label="关闭"><StudioIcon name="close"/></button></header><div class="action-list"><button v-for="item in filteredGenMenu" :key="item.id" class="action-item" @click="pickGenType(item)"><span class="action-name">{{ item.name }}</span><span class="action-code">{{ item.code }}</span></button><p v-if="!filteredGenMenu.length" class="action-empty">暂无可用的类型</p></div></div></div><BatchSingleImageTaskModal :open="batchSingleTaskOpen" :generation-type="batchSingleTaskType" :resource-ids="selectedImageIds" @close="batchSingleTaskOpen=false;batchSingleTaskType=null" @created="batchSingleTaskCreated" /><ImageGalleryViewer :open="galleryOpen" :images="galleryImages" :start-id="galleryStartId" :folders="flat" :folder-id="galleryFolderId" :loading="galleryLoading" @folder-change="changeGalleryFolder" @close="galleryOpen=false" /></div></template>
<style scoped>.heading{display:flex;align-items:flex-end;justify-content:space-between;gap:14px}.heading h1{margin-top:14px}.storage-summary{display:flex;align-items:center;gap:9px;margin:7px 0 0;font-size:12px}.storage-summary b{color:var(--v2-text);font-size:13px}.storage-summary span{color:var(--v2-text-muted)}.upload-notice,.upload-error{margin:6px 0 0;font-size:12px}.upload-notice{color:var(--ws-success)}.upload-error{color:var(--ws-danger)}.head-actions,.folder-actions,.drawer-actions{display:flex;gap:8px}.library{display:grid;grid-template-columns:255px 1fr;gap:16px}.mobile-folder-bar{display:none}.folder-panel{height:max-content;position:sticky;top:90px}.folder-tools{margin-bottom:10px;display:flex;align-items:center;gap:6px}.folder-tools b{flex:1}.folder-tools button{color:var(--v2-text-muted);background:transparent;border:0;cursor:pointer;font-size:11px}.folder-actions{margin-top:12px;padding-top:12px;border-top:1px solid var(--v2-border)}.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto;align-items:end;gap:10px}.resource-grid{margin-top:15px;display:grid;grid-template-columns:repeat(5,minmax(145px,1fr));gap:12px}.empty{grid-column:1/-1;padding:70px;text-align:center;color:var(--v2-text-muted)}.load-more{padding:20px;display:flex;justify-content:center}.drawer-actions{margin-top:18px}
